mapper.select:
SELECT 
FROM `error_log`

    AND trace_id LIKE CONCAT('%', #{traceId}, '%')
    AND operator_name LIKE CONCAT('%', #{operatorName}, '%')
    AND request_uri LIKE CONCAT('%', #{requestUri}, '%')
    AND handle_status = #{handleStatus}
    AND create_time >= #{startTime}
    AND create_time <= #{endTime}

ORDER BY create_time DESC, id DESC
